arguments.command:
# Try with llvm-symbolizer for better results, especially for the $d entries
cd /tmp

# Check if llvm-symbolizer is available
which llvm-symbolizer 2>/dev/null && {
  for off in 0x222098 0x2241ac 0x1abc80 0x16de04 0x2f4b20 0x2f4c84 0x2c1a40; do
    echo "=== $off ==="
    llvm-symbolizer --obj=libmonosgen-2.0.so.dbg "$off" 2>&1
    echo
  done
} || {
  # Fallback: use nm to find enclosing function for problematic offsets
  echo "Using nm for lookup..."
  for off in 0x2f4b20 0x2f4c84; do
    dec=$((off))
    echo -n "$off => "
    # Find the nearest function symbol at or before this offset
    aarch64-linux-gnu-nm -C libmonosgen-2.0.so.dbg 2>/dev/null | awk -v addr="$dec" '
      $2 ~ /[tTwW]/ { 
        val = strtonum("0x" $1)
        if (val <= addr) { name=$3; faddr=val }
      }
      END { printf "%s+0x%x\n", name, addr-faddr }
    ' || nm -C libmonosgen-2.0.so.dbg 2>/dev/null | awk -v addr="$dec" '
      $2 ~ /[tTwW]/ { 
        val = strtonum("0x" $1)
        if (val <= addr) { name=$3; faddr=val }
      }
      END { printf "%s+0x%x\n", name, addr-faddr }
    '
  done
}

