cd /tmp
# Use readelf to dump ALL symbols (not just FUNC) near these addresses
readelf -sW libmonosgen-2.0.so.dbg 2>/dev/null | awk '
{
  addr = strtonum("0x"$2)
  if (addr >= 0x2f4000 && addr <= 0x2f5000) print
}' | head -30

echo "=== Also check .dynsym ==="
